import { createClient } from '@supabase/supabase-js'

const supabaseUrl = import.meta.env.VITE_SUPABASE_URL
const supabaseAnonKey = import.meta.env.VITE_SUPABASE_ANON_KEY

if (!supabaseUrl || !supabaseAnonKey) {
  throw new Error('Missing Supabase environment variables. Please check your .env.local file.')
}

export const supabase = createClient(supabaseUrl, supabaseAnonKey)

import { useState, useEffect } from 'react'
import { useAuth } from '../contexts/AuthContext'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Mountain, Package, MapPin, Weight, Plus, LogOut, User, X, Upload, FileText } from 'lucide-react'
import { AddGearForm } from '@/components/gear/AddGearForm'
import { ImportGearForm } from '@/components/gear/ImportGearForm'
import { supabase } from '@/lib/supabase'
import { captureError } from '@/lib/sentry'
import { toast } from '@/hooks/useToast'
import type { ParsedGearItem } from '@/utils/csvParser'

export function Dashboard() {
  const { user, signOut } = useAuth()
  const [showAddGear, setShowAddGear] = useState(false)
  const [showImport, setShowImport] = useState(false)
  const [gearCount, setGearCount] = useState(0)

  // Fetch initial gear count on component mount
  useEffect(() => {
    const fetchGearCount = async () => {
      if (!user) return

      try {
        const { count, error } = await supabase
          .from('gear_items')
          .select('*', { count: 'exact', head: true })
          .eq('user_id', user.id)

        if (error) throw error

        if (count !== null) {
          setGearCount(count)
        }
      } catch (error) {
        captureError(error as Error, {
          component: 'Dashboard',
          action: 'fetchGearCount'
        })
        // Don't show error toast on initial load
        console.error('Failed to load gear count:', error)
      }
    }

    fetchGearCount()
  }, [user])

  const handleAddGear = async (gear: {
    name: string
    weight_grams: number
    category: string
    quantity: number
    worn: boolean
    consumable: boolean
    notes?: string | null
    price?: number | null
    description?: string | null
    image_url?: string | null
    brand?: string | null
  }) => {
    if (!user) return

    try {
      // Ensure all optional fields are properly handled
      const gearData = {
        user_id: user.id,
        name: gear.name,
        weight_grams: gear.weight_grams,
        category: gear.category,
        quantity: gear.quantity,
        worn: gear.worn,
        consumable: gear.consumable,
        notes: gear.notes || null,
        price: gear.price || null,
        description: gear.description || null,
        image_url: gear.image_url || null,
        brand: gear.brand || null
      }

      const { error } = await supabase
        .from('gear_items')
        .insert(gearData)

      if (error) {
        console.error('Supabase error details:', error)
        console.error('Data that failed:', gearData)
        throw error
      }

      // Update gear count
      setGearCount(prev => prev + 1)

      // Close the form
      setShowAddGear(false)

      // Show success toast with item name
      const itemName = gear.brand ? `${gear.brand} ${gear.name}` : gear.name
      toast.success(`✓ ${itemName} added to your gear library`)
    } catch (error) {
      captureError(error as Error, {
        component: 'Dashboard',
        action: 'handleAddGear'
      })
      console.error('Error adding gear:', error)
      toast.error('Failed to add gear', 'Please try again or check your connection.')
    }
  }

  const handleImportGear = async (items: ParsedGearItem[]) => {
    if (!user) return

    try {
      // Transform ParsedGearItem to match our database schema
      const gearItems = items.map(item => ({
        user_id: user.id,
        name: item.name,
        brand: item.brand || null,
        weight_grams: item.weight_grams,
        category: item.category,
        quantity: item.quantity,
        worn: item.worn,
        consumable: item.consumable,
        price: item.price || null,
        notes: item.notes || null,
        description: item.description || null
      }))

      // Bulk insert all items
      const { data, error } = await supabase
        .from('gear_items')
        .insert(gearItems)
        .select()

      if (error) throw error

      // Update gear count
      setGearCount(prevCount => prevCount + items.length)

      // Close import form
      setShowImport(false)

      // Show success message
      toast.success(
        `Successfully imported ${items.length} items!`,
        'Your gear has been added to your library.'
      )

      // Refresh the page data if needed
      // You might want to trigger a re-fetch of gear items here
    } catch (error) {
      captureError(error as Error, {
        component: 'Dashboard',
        action: 'importGear',
        metadata: { itemCount: items.length }
      })
      console.error('Error importing gear:', error)
      toast.error('Failed to import gear', 'Please try again or import fewer items at once.')
    }
  }

